import pandas as pd

def clean(df):
    df = df.copy()

    # Normalize text fields and fix category label variants.
    for col in ["Product", "Category", "Region"]:
        if col in df.columns:
            df[col] = df[col].astype("string").str.strip()

    if "Category" in df.columns:
        df["Category"] = df["Category"].replace({
            "Furnture": "Furniture",
            "Accesories": "Accessories"
        })

    # Remove exact duplicate rows, then enforce unique order numbers.
    df = df.drop_duplicates()
    if "Order_ID" in df.columns:
        df = df.drop_duplicates(subset=["Order_ID"], keep="first")

    # Drop rows without a region because region is the grouping key.
    if "Region" in df.columns:
        df = df.dropna(subset=["Region"])

    # Ensure numeric types and consistent revenue.
    if "Quantity" in df.columns:
        df["Quantity"] = pd.to_numeric(df["Quantity"], errors="coerce")
    if "Price" in df.columns:
        df["Price"] = pd.to_numeric(df["Price"], errors="coerce")
    if {"Quantity", "Price", "Revenue"}.issubset(df.columns):
        df["Revenue"] = df["Quantity"] * df["Price"]

    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby("Region", dropna=True)["Quantity"].sum()
    return {str(region): int(units) for region, units in grouped.items()}
